/* CasaPorta demo: UI calls service methods; replace Mock* adapters with API adapters. */
const photos=[
 'https://images.unsplash.com/photo-1600607687939-ce8a6c25118c?auto=format&fit=crop&w=900&q=85',
 'https://images.unsplash.com/photo-1600566753086-00f18fb6b3ea?auto=format&fit=crop&w=900&q=85',
 'https://images.unsplash.com/photo-1600047509807-ba8f99d2cdde?auto=format&fit=crop&w=900&q=85',
 'https://images.unsplash.com/photo-1600607687920-4e2a09cf159d?auto=format&fit=crop&w=900&q=85'
];
const seed=()=>({role:'b2c',page:'home',budget:null,lead:null,verified:false,matches:false,interested:false,token:350,transactions:[],offers:[],messages:[{from:'Firma',text:'Merhaba Ahmet Bey, Fethiye Merkez’deki dairemiz talebinize uygun görünüyor.',time:'10:24'}],contact:{b2c:false,b2b:false,open:false},appointments:[],propertyAdded:false,propertyApproved:false,paused:false,chatStarted:false,feedback:null,activeLead:false,adminUsers:[{id:'admin-1',name:'Operasyon Admini',email:'admin@casaporta.demo',role:'admin',active:true}],categories:[],disabledCategoryIds:[],categorySearch:'',moderatedLeadIds:[]});
let state; try{state={...seed(),...JSON.parse(localStorage.getItem('casaporta-demo')||'{}')}}catch{state=seed()}
const save=()=>localStorage.setItem('casaporta-demo',JSON.stringify(state));
const app=document.querySelector('#app');let modal=null,wizard=null,budgetStep=0,budgetVals={income:'',debt:'',down:'',term:'60',energyClass:'other',ownsHome:false};
const properties=[
 {title:'Aydınlık 2+1 Daire',place:'Fethiye Merkez',price:'₺5.250.000',sqm:'110 m²',rooms:'2+1',score:92,photo:photos[0],features:'Balkon · Asansör · Otopark',why:'Bütçene uygun, Fethiye Merkez’de ve oturum amaçlı talebinle örtüşüyor.'},
 {title:'Bahçe Katı 2+1',place:'Fethiye, Taşyaka',price:'₺5.650.000',sqm:'105 m²',rooms:'2+1',score:88,photo:photos[1],features:'Bahçe · Yeni bina · Otopark',why:'Bütçe aralığının içinde, benzer oda planı ve merkezi konum.'},
 {title:'Deniz Manzaralı 2+1',place:'Fethiye, Çalış',price:'₺5.900.000',sqm:'118 m²',rooms:'2+1',score:84,photo:photos[2],features:'Deniz manzarası · Balkon',why:'Üst bütçe sınırında, Çalış sahiline yakın ve taşınmaya hazır.'},
 {title:'Modern 3+1 Daire',place:'Fethiye Merkez',price:'₺6.150.000',sqm:'132 m²',rooms:'3+1',score:79,photo:photos[3],features:'Ebeveyn banyosu · Kapalı otopark',why:'Geniş yaşam alanı sunuyor; bütçenin biraz üzerinde.'}
];
const leads=[
 {tier:'GOLD LEAD',place:'Fethiye / Çalış',rooms:'2+1',budget:'₺5–6M',budgetTotal:6500000,cash:3000000,loan:1500000,swap:2000000,purpose:'Konut',token:4,age:'4 dk önce',timing:'2 hafta içinde',note:'Müşteri ile görüşüldü. 3M nakit, 1.5M kredi teyit edildi. Afaki durum yok, 2 hafta içinde alım niyetinde. Takas aracı ekspertiz raporu mevcut.',trade:'2022 model SUV + 1+1 daire takası'},
 {tier:'SILVER LEAD',place:'Fethiye / Merkez',rooms:'3+1',budget:'₺7–8M',budgetTotal:7800000,cash:4000000,loan:2800000,swap:1000000,purpose:'Oturum',token:6,age:'18 dk önce',timing:'1 ay içinde',note:'Bölge ve bütçe teyit edildi. Aile taşınma planını bu dönem içinde tamamlamak istiyor.',trade:'Aracı takas seçeneği değerlendirilebilir'},
 {tier:'BRONZE LEAD',place:'Ortaca',rooms:'Arsa',budget:'₺2–3M',budgetTotal:2500000,cash:1500000,loan:1000000,swap:0,purpose:'Yatırım',token:3,age:'42 dk önce',timing:'1–3 ay içinde',note:'İmar durumu ve altyapı öncelikli. Alım bütçesi müşteriyle ön görüşmede netleştirildi.',trade:'Takas düşünülmüyor'}
];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>'₺'+Math.round(n).toLocaleString('tr-TR');
const allCategories=()=>[...CasaCategories.categories.filter(c=>!state.disabledCategoryIds.includes(c.id)),...(state.categories||[])];
const categoryOptions=selected=>CasaCategories.roots.map(root=>[...new Set(allCategories().filter(c=>c.rootId===root.id).map(c=>c.group))].map(group=>`<optgroup label="${root.title} · ${group}">${allCategories().filter(c=>c.rootId===root.id&&c.group===group).map(c=>`<option value="${c.id}" ${selected===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</optgroup>`).join('')).join('');
const isAdmin=()=>state.role==='admin'||state.role==='superadmin';
const toast=msg=>{let t=document.querySelector('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(window._tt);window._tt=setTimeout(()=>t.classList.remove('show'),2500)};
const b=(label,action,cls='btn')=>`<button class="${cls}" data-action="${action}">${label}</button>`;
function header(){return `<header class="topbar"><div class="brand"><img class="brand-logo" src="assets/casaporta-logo.png" alt="CASAPORTA"></div><div class="top-actions"><span class="demo-tag">DEMO MODU</span>${state.role==='b2c'?b('Firma girişi','role-b2b','btn quiet small'):''}${b('Rolü değiştir','roles','btn small')}</div></header>`}
const menus={b2c:[['home','Ana sayfa','⌂'],['dashboard','Taleplerim','▤'],['matches','Eşleşmeler','⌕'],['chat','Mesajlar','✉'],['appointments','Randevular','◷']],b2b:[['dashboard','Dashboard','⌂'],['leads','Talepler','⌕'],['properties','Portföyler','▦'],['offers','Teklifler','↗'],['chat','Mesajlar','✉'],['tokens','Coin & Paket','◈']],developer:[['dashboard','Proje paneli','⌂'],['leads','Proje talepleri','⌕'],['properties','Projeler','▦'],['offers','Teklifler','↗'],['chat','Mesajlar','✉'],['tokens','Coin & Paket','◈']],admin:[['admin','Operasyon paneli','⌘'],['properties','Portföy inceleme','▦'],['leads','Talep moderasyonu','⌕'],['tokens','Coin hareketleri','◈']],superadmin:[['superadmin','Süperadmin','♛'],['categories','Kategori yönetimi','▦'],['admin','Operasyon paneli','⌘'],['properties','Portföy inceleme','▦'],['leads','Talep moderasyonu','⌕'],['tokens','Coin hareketleri','◈']]};
function shell(content){let menu=menus[state.role]||menus.b2c;return `${header()}<div class="shell"><aside class="sidebar"><div class="side-org"><b>${state.role==='b2c'?'Ahmet Yılmaz':state.role==='b2b'?'Fethiye Prime Gayrimenkul':state.role==='developer'?'Fethiye Yapı Proje':state.role==='superadmin'?'CasaPorta Süperadmin':'CasaPorta Operasyon'}</b><span>${state.role==='b2c'?'Alıcı hesabı':state.role==='b2b'?'Emlak ofisi':state.role==='developer'?'İnşaat / Proje':state.role==='superadmin'?'Tam yetkili platform yöneticisi':'Operasyon yöneticisi'}</span></div><nav class="nav">${menu.map(([p,n])=>`<button class="${state.page===p?'active':''}" data-nav="${p}">${n}</button>`).join('')}<button data-action="roles">⇄ &nbsp; Demo rolü</button><button data-action="reset">↺ &nbsp; Demo verisini sıfırla</button></nav></aside><main class="main">${content}</main></div><nav class="mobile-nav">${menu.slice(0,5).map(([p,n,i])=>`<button class="${state.page===p?'active':''}" data-nav="${p}"><b>${i}</b>${n}</button>`).join('')}</nav>`}
function home(){return `${header()}<section class="hero"><div><div class="eyebrow">DAHA İYİ BİR BAŞLANGIÇ</div><h1>Gayrimenkul aramaya değil,<br><span>ihtiyacını anlatmaya</span><br>başla.</h1><p class="hero-copy">Bütçeni hesapla, ihtiyacını oluştur. CasaPorta sana uygun doğrulanmış portföyleri bulsun.</p><div class="hero-cta">${b('Bütçemi Hesapla','budget','btn primary')}${b('Nasıl çalışır?','how','btn')}</div><p class="hero-note">Ücretsiz ön bütçe simülasyonu · 2 dakikada talep oluştur</p></div><div class="visual"><div class="floating float-match"><div class="float-title">Sana uygun eşleşme</div><div class="match-score">%92 eşleşme</div><div class="muted" style="font-size:12px">Bütçe · Konum · İhtiyaç</div></div><div class="floating float-home"><div class="mini-house"><div class="mini-pic"></div><div><b style="font-size:13px">Aydınlık 2+1 Daire</b><div class="muted" style="font-size:12px;margin-top:4px">Fethiye Merkez · ₺5,25M</div></div></div></div></div></section><section class="section" id="how"><div class="section-head"><div><div class="eyebrow">BASİTÇE İLERLE</div><h2>Doğru ev, doğru eşleşmeyle başlar.</h2></div><p>Aradığın şeyi anlat. İhtiyacına uyan doğrulanmış seçenekleri tek yerde gör.</p></div><div class="steps">${[['01','Bütçeni belirle','Ön bütçeni birkaç adımda hesapla.'],['02','Talebini oluştur','Konumunu, ihtiyacını ve zamanını anlat.'],['03','Eşleşmeleri incele','Sana uygun doğrulanmış portföyleri gör.'],['04','Görüşmeye geç','Teklif, mesaj ve randevunu tek yerden yönet.']].map(x=>`<div class="step-card"><div class="step-num">${x[0]}</div><h3>${x[1]}</h3><p>${x[2]}</p></div>`).join('')}</div></section><footer class="footer"><span>CASAPORTA · İhtiyacını anlat.</span><span>Demo ortamı · Veriler bu tarayıcıda saklanır</span></footer>`}
function heading(title,sub,action=''){return `<div class="main-title"><div><h2>${title}</h2><p>${sub}</p></div>${action}</div>`}
function propertyCard(p,i){return `<article class="card property"><div class="property-photo" style="background-image:url('${p.photo}')"><span class="tag">Doğrulanmış profesyonel portföyü</span></div><div class="property-body"><div class="property-row"><h3>${p.title}</h3><span class="tag">%${p.score}</span></div><p style="font-size:13px;margin:3px 0 8px">${p.place}</p><div class="price">${p.price}</div><div class="property-meta"><span>${p.sqm}</span><span>${p.rooms}</span></div><div class="property-row">${b('Detayı gör','property-'+i,'btn small')}${b('İlgileniyorum','interested-'+i,'btn primary small')}</div></div></article>`}
function dashboard(){
 if(state.role==='b2c'){
  const title=state.paused?'Talep duraklatıldı':state.lead?'Talebin aktif':'Demo hesabı';
  const content=!state.lead?`<div class="card soft" style="margin-bottom:18px"><div class="eyebrow">İLK ADIM</div><h3 style="margin-top:12px">Henüz bir talebin yok.</h3><p>İhtiyacını anlat, sana uygun doğrulanmış portföyleri bulalım.</p>${b('İlk talebini oluştur','budget','btn primary')}</div>`:`<div class="grid cols-3" style="margin-bottom:18px"><div class="card"><span class="label">Uygun portföy</span><div class="metric">${state.matches?'7':'—'}</div><span class="label">Talebine göre</span></div><div class="card"><span class="label">Teklif</span><div class="metric">${state.offers.length||'1'}</div><span class="label">Yanıt bekliyor</span></div><div class="card"><span class="label">Aktif görüşme</span><div class="metric">${state.chatStarted||state.interested?'1':'—'}</div><span class="label">Firma ile</span></div></div><div class="grid cols-2"><div class="card"><div class="property-row"><h3>Aktif talebin</h3>${b('Düzenle','edit-lead','link-btn')}</div><div class="separator"></div><div class="price">${state.lead.place} · ${state.lead.rooms}</div><p>${state.lead.budget||'₺5–6M'} · ${state.lead.purpose} · ${state.lead.when}</p><div class="callout">${state.paused?'Talebin şu anda duraklatıldı.':'Talebin eşleşme aramaya devam ediyor.'}</div><div style="display:flex;gap:8px;margin-top:15px;flex-wrap:wrap">${b(state.paused?'Devam ettir':'Duraklat','pause','btn small')}${b('Yenile','renew','btn small')}${b('Talebi kapat','close-lead','btn quiet small')}</div></div><div class="card"><h3>Talep yolculuğun</h3><div class="timeline" style="margin-top:18px">${[['Talep oluşturuldu',true],['Telefon ve e-posta doğrulandı',state.verified],['Eşleşmeler bulundu',state.matches],['Teklif geldi',true],['Görüşme',state.chatStarted||state.interested],['Randevu',state.appointments.length>0]].map(x=>`<div class="timeline-row ${x[1]?'done':''}"><span class="dot">${x[1]?'✓':''}</span><span>${x[0]}</span></div>`).join('')}</div></div></div>${state.matches?`<div style="margin-top:22px">${heading('Öne çıkan eşleşmeler','Talebine göre sıralandı.',b('Tüm eşleşmeleri gör','nav-matches','link-btn'))}<div class="grid cols-2">${properties.slice(0,2).map(propertyCard).join('')}</div></div>`:''}`;
  return `${heading('Merhaba Ahmet','Talebinin ilerleyişi ve sana uygun seçenekler burada.',`<span class="tag">${title}</span>`)}${content}`;
 }
 if(state.role==='b2b'||state.role==='developer'){
  const de=state.role==='developer';
  return `${heading(de?'Fethiye Yapı Proje':'Fethiye Prime Gayrimenkul',de?'Projelerin ve proje talebi eşleşmelerin.':'İşine uygun talepler ve eşleşmeler tek yerde.',`<span class="tag">${de?'PROJE GELİŞTİRİCİ':'EMLAK OFİSİ'}</span>`)}<div class="grid cols-3" style="margin-bottom:18px"><div class="card"><span class="label">Uygun talep</span><div class="metric">${state.activeLead?'11':'12'}</div><span class="label">Bölgenle eşleşen</span></div><div class="card"><span class="label">Yeni eşleşme</span><div class="metric">4</div><span class="label">Son 7 günde</span></div><div class="card token-big"><span class="label">Coin bakiyesi</span><div class="metric">${state.token}</div><span class="label">Kullanıma hazır</span></div></div><div class="grid cols-2"><div class="card"><div class="eyebrow">BUGÜNÜN FIRSATLARI</div><h3 style="margin-top:12px">Yeni taleplere göz at</h3><p>Fethiye ve çevresinde ihtiyacına uygun müşterileri keşfet.</p>${b('Uygun talepleri gör','nav-leads','btn primary')}</div><div class="card"><div class="eyebrow">PORTFÖY YÖNETİMİ</div><h3 style="margin-top:12px">${de?'Fethiye Modern':'Portföyünü eşleştir'}</h3><p>${de?'32 daire · 1+1 / 2+1 / 3+1 · Teslim 2027':'Linkten portföy ekle veya mevcut portföyünden teklif oluştur.'}</p>${b(de?'Projeleri gör':'Portföy ekle','nav-properties','btn')}</div></div><div class="card" style="margin-top:18px"><div class="property-row"><h3>Son hareketler</h3>${b('Coin hareketleri','nav-tokens','link-btn')}</div><div class="timeline-row done" style="margin-top:15px"><span class="dot">✓</span><span>Fethiye · 2+1 için yeni bir talep yayınlandı</span><span class="muted" style="margin-left:auto">4 dk</span></div><div class="timeline-row"><span class="dot">↗</span><span>Yeni eşleşmelerini görmek için talepleri incele</span></div></div>`;
 }
 return `${heading('Admin paneli','Platform etkinliği ve inceleme kuyruğu.','<span class="tag gold">YÖNETİCİ</span>')}<div class="grid cols-3"><div class="card"><span class="label">Kullanıcılar</span><div class="metric">1.284</div></div><div class="card"><span class="label">Aktif talepler</span><div class="metric">326</div></div><div class="card"><span class="label">İnceleme bekleyen</span><div class="metric">${state.propertyAdded&&!state.propertyApproved?'1':'8'}</div></div></div><div style="margin-top:22px">${adminView()}</div>`;
}
function matchesView(){return `${heading('Sana uygun portföyler',state.matches?'Talebinle eşleşen doğrulanmış seçenekler.':'Eşleşmeleri görmek için önce talebini oluştur.',state.matches?'<span class="tag">7 UYGUN EŞLEŞME</span>':'')}${state.matches?`<div class="callout" style="margin-bottom:18px">Eşleşmeler bütçe, konum, gayrimenkul tipi, oda sayısı ve ihtiyacına göre sıralanır.</div><div class="grid cols-2">${properties.map(propertyCard).join('')}</div>`:`<div class="empty"><h3>Henüz eşleşme yok</h3><p>Talebini oluşturduğunda CasaPorta sana uygun doğrulanmış portföyleri bulur.</p>${b('Bütçemi hesapla','budget','btn primary')}</div>`}`}
function leadsView(){return `${heading(state.role==='developer'?'Proje talepleri':'Uygun talepler','Bölgenle eşleşen doğrulanmış müşteri talepleri.',`<span class="token-balance-pill">◉ &nbsp;${state.token} Coin</span>`)}<div class="lead-list">${leads.map((l,i)=>{if(!isAdmin()&&(state.moderatedLeadIds||[]).includes(i))return '';const insufficient=state.token<l.token, opened=state.activeLead&&i===0;return `<article class="lead-deal-card ${l.tier.startsWith('GOLD')?'lead-gold':''}"><div class="lead-topline"><span class="lead-tier ${l.tier.startsWith('GOLD')?'is-gold':l.tier.startsWith('SILVER')?'is-silver':'is-bronze'}">◉ &nbsp;${l.tier==='GOLD LEAD'?'Altın Lead':l.tier==='SILVER LEAD'?'Gümüş Lead':'Bronz Lead'}</span><span class="lead-cost">◉ &nbsp;${l.token} Coin</span></div><div class="lead-matchline">Bütçe ve portföy birebir uyuşuyor</div><div class="lead-facts"><span>♧ &nbsp;${l.place}</span><span>◷ &nbsp;${l.timing}</span><span class="lead-purpose">${l.purpose}</span></div><section class="lead-total"><span>Toplam bütçe</span><strong>${money(l.budgetTotal)}</strong></section><div class="lead-split"><div><span>▱ &nbsp;Peşinat</span><strong>${money(l.cash)}</strong></div><div><span>▤ &nbsp;Kredi</span><strong>${money(l.loan)}</strong></div><div><span>⇄ &nbsp;Takas</span><strong>${money(l.swap)}</strong></div></div><section class="lead-verification"><strong>✓ &nbsp;Çağrı Merkezi Doğrulama Notu</strong><p>${l.note}</p><span>Takas: ${l.trade}</span></section><div class="lead-contact"><div><span>${i===0?'M. K.':i===1?'S. K.':'M. D.'} · Numara gizli</span><div class="blur-number">•••• ••• •• ••</div></div><button class="lead-access" data-action="${insufficient?'buy-coins':'access-'+i}" ${opened?'disabled':''}>◉ &nbsp;${opened?'Talep açıldı':insufficient?'Coin paketi seç':`${l.token} Coin Harca`}</button></div>${insufficient?`<p class="lead-error">Yetersiz Coin. Bu lead için ${l.token} Coin gerekli. ${b('Coin paketlerini gör','buy-coins','link-btn')}</p>`:''}</article>`}).join('')}</div>`}
function propertiesView(){return `${heading(state.role==='developer'?'Projelerim':'Portföylerim','Portföylerini yönet, yeni ilan bağlantısı ekle.',b(state.role==='developer'?'Proje ekle':'Portföy ekle','add-property','btn primary'))}${state.propertyAdded?`<div class="card" style="margin-bottom:16px"><div class="property-row"><div><h3>Fethiye Merkez · 2+1 Daire</h3><p style="margin:4px 0">₺5.250.000 · 110 m² · ${esc(state.selectedListingCategory||'Kategori seçilmedi')}</p></div><span class="tag ${state.propertyApproved?'':'gold'}">${state.propertyApproved?'Doğrulandı':'Manuel doğrulama bekliyor'}</span></div><div class="separator"></div><div class="property-meta"><span>✓ Fiyat</span><span>✓ Konum</span><span>✓ Aktiflik</span><span>✓ Veri tutarlılığı</span><span>✓ Duplicate</span></div></div>`:''}${state.role==='developer'?`<div class="grid cols-2"><div class="card"><span class="tag">AKTİF PROJE</span><h3 style="margin-top:15px">Fethiye Modern</h3><p>32 daire · 1+1 / 2+1 / 3+1 · Teslim 2027</p>${b('Proje detayları','project-detail','btn small')}</div></div>`:state.propertyAdded?`<div class="notice">Portföy kontrol edildi. Admin onayı sonrasında eşleşmelerde görünür.</div>`:`<div class="empty"><h3>Portföy listen burada</h3><p>İlan bağlantısını ekleyerek bilgileri otomatik çıkar ve kontrol et.</p>${b('İlan bağlantısı ekle','add-property','btn primary')}</div>`}`}
function offersView(){return `${heading('Teklifler','Gönderdiğin ve aldığın teklifler.')}${state.offers.length?`<div class="grid">${state.offers.map(o=>`<div class="card"><div class="property-row"><div><h3>${o.title}</h3><p style="margin:3px 0">${o.desc}</p></div><span class="tag">${o.status}</span></div><div class="property-row"><span class="label">${o.date}</span>${b('Mesaja geç','nav-chat','btn small')}</div></div>`).join('')}</div>`:`<div class="card"><div class="property-row"><div><span class="tag">YENİ TEKLİF</span><h3 style="margin-top:12px">Ahmet’in Fethiye talebiyle eşleşme</h3><p>2+1 · ₺5–6M · Oturum</p></div>${b('Talebi incele','nav-leads','btn primary')}</div></div>`}`}
function tokensView(){return `${heading('Coin & Paket','Coin bakiyeni, paketlerini ve hareketlerini takip et.',`<div class="heading-actions">${b('Coin satın al','buy-coins','btn primary')}${b('Abonelik paketleri','packages','btn')}</div>`)}<div class="grid cols-2"><div class="card token-big"><span class="label">Kullanılabilir Coin</span><div class="metric">${state.token}</div><p>Coinler talep erişiminde kullanılır.</p>${b('Coin yükle','buy-coins','btn small')}</div><div class="card"><span class="label">Mevcut abonelik</span><div class="metric" style="font-size:24px">${state.role==='developer'?'Proje Pro':'Pro'}</div><p>Ayda 100 Coin · 20 aktif portföy</p>${b('Abonelik paketleri','packages','btn small')}</div></div><div class="card" style="margin-top:18px"><h3>Coin hareketleri</h3>${state.transactions.length?state.transactions.map(t=>`<div class="table-row"><span>${t.note}</span><span>${t.date}</span><b style="color:${t.amount<0?'#ff7777':'var(--green)'}">${t.amount>0?'+':''}${t.amount} Coin</b><span>Bakiye ${t.balance} Coin</span></div>`).join(''):`<div class="empty" style="margin-top:12px"><p>Henüz Coin hareketi yok.</p></div>`}</div>`}
function chatView(){return `${heading('Mesajlar',state.role==='b2c'?'Eşleştiğin firmayla güvenli şekilde konuş.':'Müşterilerinle uygulama içinde iletişim kur.')}${!state.chatStarted&&!state.interested&&state.role==='b2c'?`<div class="empty"><h3>Henüz bir görüşmen yok</h3><p>Bir portföyle ilgilendiğinde mesajlaşma alanı açılır. Telefon ve e-posta karşılıklı onay olmadan paylaşılmaz.</p>${b('Eşleşmeleri gör','nav-matches','btn primary')}</div>`:`<div class="card"><div class="property-row"><div><h3>${state.role==='b2c'?'Fethiye Prime Gayrimenkul':'Ahmet Yılmaz'}</h3><span class="label">Fethiye Merkez · 2+1 Daire</span></div><span class="tag">GÜVENLİ SOHBET</span></div><div class="separator"></div><div class="messages">${state.messages.map(m=>`<div class="bubble ${m.from===(state.role==='b2c'?'Ahmet':'Firma')?'mine':''}">${esc(m.text)}<small>${esc(m.from)} · ${m.time}</small></div>`).join('')}</div><div class="message-compose"><input id="message-input" aria-label="Mesaj yaz" placeholder="Mesajını yaz...">${b('Gönder','send-message','btn primary small')}</div><div class="separator"></div><div class="property-row"><div><b style="font-size:13px">İletişim bilgilerini paylaş</b><div class="label">İki taraf da onayladığında bilgiler açılır.</div></div>${b(state.contact[state.role==='b2c'?'b2c':'b2b']?'Onay verdin':'İletişimimi paylaş','unlock-contact','btn small')}</div>${state.contact.open?`<div class="result-card" style="margin-top:15px"><b>İletişim bilgileri açıldı</b><p>+90 532 555 01 24 · merhaba@fethiyeprime.demo</p>${b('Randevu oluştur','appointment','btn')}</div>`:state.contact[state.role==='b2c'?'b2c':'b2b']?`<div class="notice" style="margin-top:12px">Sen onay verdin. Diğer taraf onay verince iletişim bilgileri açılacak.</div>`:''}<div style="margin-top:15px">${b('Randevu oluştur','appointment','btn')}</div></div>`}`}
function appointmentsView(){return `${heading('Randevular','Planlanan görüşmeler ve tamamlanan randevular.',b('Randevu oluştur','appointment','btn primary'))}${state.appointments.length?`<div class="grid">${state.appointments.map(a=>`<div class="card"><div class="property-row"><div><h3>${a.date} · ${a.time}</h3><p>${a.note||'Fethiye Prime Gayrimenkul ile görüşme'}</p></div><span class="tag">PLANLANDI</span></div>${b('Sonucu ekle','feedback','btn small')}</div>`).join('')}</div>`:`<div class="empty"><h3>Henüz randevun yok</h3><p>Bir portföyle ilgilendiğinde uygun bir görüşme zamanı belirleyebilirsin.</p>${b('Eşleşmeleri incele','nav-matches','btn')}</div>`}`}
function adminView(){return `${heading(state.role==='superadmin'?'Süperadmin · Operasyon':'Operasyon admin paneli','Portföy doğrulama, ilan ve talep moderasyonu.',`<span class="tag gold">${state.role==='superadmin'?'SÜPERADMIN':'ADMIN'}</span>`)}<div class="grid cols-3" style="margin-bottom:18px">${[['Kullanıcılar','1.284'],['Aktif talepler','326'],['İnceleme bekleyen',state.propertyAdded&&!state.propertyApproved?'1':'8']].map(x=>`<div class="card"><span class="label">${x[0]}</span><div class="metric" style="font-size:25px">${x[1]}</div></div>`).join('')}</div><div class="card"><div class="property-row"><div><span class="eyebrow">DOĞRULAMA KUYRUĞU</span><h3 style="margin-top:11px">Manuel doğrulama bekleyen portföyler</h3></div><span class="tag gold">${state.propertyAdded&&!state.propertyApproved?'1 BEKLEYEN':'8 BEKLEYEN'}</span></div>${state.propertyAdded&&!state.propertyApproved?`<div class="admin-row"><span><b>Fethiye Merkez · 2+1</b><br><span class="muted">₺5.250.000 · Fethiye Prime Gayrimenkul</span></span><span>Otomatik kontrol geçti</span><span>Bugün</span><span>${b('İncele','review-property','btn small')}</span></div>`:`<div class="admin-row"><span><b>Çalış · 3+1 Daire</b><br><span class="muted">₺7.800.000 · Fethiye Prime Gayrimenkul</span></span><span>Kontrol tamamlandı</span><span>Bugün</span><span>${b('İncele','review-sample','btn small')}</span></div>`}</div><div class="grid cols-2" style="margin-top:18px"><div class="card"><span class="eyebrow">ADMIN YETKİLERİ</span><div class="timeline" style="margin-top:12px">${['İlan ve firma belgelerini incele / onayla / reddet','Talepleri ve ilan içeriğini moderasyona al','Kullanıcı desteği ve coin hareketlerini görüntüle','Kategori kataloğu, yönetici hesabı ve platform ayarlarını değiştiremez'].map(x=>`<div class="timeline-row"><span class="dot">✓</span><span>${x}</span></div>`).join('')}</div></div><div class="card"><span class="eyebrow">İŞLEM KAYDI</span><p style="margin-top:12px">${state.propertyApproved?'Portföy onaylandı.':'İnceleme kuyruğunda işlem bekliyor.'}</p><p class="muted">Demo ortamındaki işlemler bu tarayıcıda saklanır; gerçek kullanıcı veya kayıt sistemine bağlanmaz.</p></div></div>`}
function superadminView(){return `${heading('Süperadmin paneli','Platform genelinde yönetişim, roller ve katalog ayarları.',`<span class="tag gold">TAM YETKİ</span>`)}<div class="grid cols-3"><div class="card"><span class="label">Yönetici hesabı</span><div class="metric">${state.adminUsers.filter(a=>a.active).length}</div></div><div class="card"><span class="label">Aktif kategori</span><div class="metric">${allCategories().length}</div></div><div class="card"><span class="label">Platform durumu</span><div class="metric" style="font-size:22px">Demo aktif</div></div></div><div class="grid cols-2" style="margin-top:18px"><div class="card"><div class="property-row"><div><span class="eyebrow">YÖNETİCİ HESAPLARI</span><h3 style="margin-top:10px">Admin erişimleri</h3></div><span class="tag">Sadece süperadmin yönetir</span></div>${(state.adminUsers||[]).map(a=>`<div class="table-row"><span><b>${esc(a.name)}</b><br><span class="muted">${esc(a.email)}</span></span><span>${a.active?'Aktif':'Pasif'}</span><span>Admin</span><span>${b(a.active?'Erişimi kapat':'Erişimi aç','toggle-admin-'+a.id,'btn small')}</span></div>`).join('')}${b('Admin hesabı ekle','create-admin-form','btn primary small')}</div><div class="card"><span class="eyebrow">PLATFORM YÖNETİMİ</span><h3 style="margin-top:10px">Katalog ve yönetişim</h3><p>196 başlangıç kategorisi, kategori görünürlüğü ve yönetici yetkileri süperadmin kontrolündedir.</p>${b('Kategori kataloğunu yönet','nav-categories','btn primary')}${b('Operasyon panelini aç','nav-admin','btn small')}</div></div><div class="notice" style="margin-top:18px">Yetki farkı prototip arayüzünde uygulanır. Gerçek yayında güvenli olması için aynı rol kontrolleri sunucu tarafında da uygulanmalıdır.</div>`}
function leadModerationView(){if(!isAdmin())return '';return `<div class="card" style="margin-top:18px"><div class="property-row"><div><span class="eyebrow">TALEP MODERASYONU</span><h3 style="margin-top:9px">Yayındaki talepler</h3></div><span class="tag">Admin / Süperadmin</span></div>${leads.map((lead,i)=>`<div class="table-row"><span><b>${esc(lead.place)} · ${esc(lead.rooms)}</b><br><span class="muted">${esc(lead.budget)} · ${esc(lead.purpose)}</span></span><span>${(state.moderatedLeadIds||[]).includes(i)?'Gizli':'Yayında'}</span><span>${esc(lead.timing)}</span><span>${b((state.moderatedLeadIds||[]).includes(i)?'Yayına al':'Gizle','moderate-lead-'+i,'btn small')}</span></div>`).join('')}</div>`}
function categoriesView(){const q=(state.categorySearch||'').trim().toLocaleLowerCase('tr-TR');const items=allCategories().filter(c=>!q||`${c.name} ${c.rootTitle} ${c.group}`.toLocaleLowerCase('tr-TR').includes(q));return `${heading('Kategori kataloğu','Gayrimenkul ve Taşınmaz başlıklarındaki aranabilir ilan/talep kategorileri.',`<span class="tag gold">${allCategories().length} AKTİF</span>`)}<div class="card"><div class="property-row"><div><h3>Yeni kategori</h3><p>Süperadmin kataloğa özel kategori ekleyebilir.</p></div></div><div class="category-create"><select id="new-category-root"><option value="gayrimenkul">Gayrimenkul</option><option value="tasinmaz">Taşınmaz</option></select><input id="new-category-name" placeholder="Örn. Günlük kiralık daire"><button class="btn primary" data-action="create-category">Ekle</button></div><div class="category-create" style="margin-top:10px"><input id="category-search" value="${esc(state.categorySearch||'')}" placeholder="Kategori, ana başlık veya grup ara">${b('Ara','filter-categories','btn')}${b('Aramayı temizle','clear-category-search','btn quiet')}</div></div><div class="category-groups">${CasaCategories.roots.map(root=>{const groupItems=items.filter(c=>c.rootId===root.id);return `<section class="card"><div class="property-row"><h3>${root.title}</h3><span class="tag">${groupItems.length} sonuç</span></div>${groupItems.length?`<div class="category-list">${groupItems.map(c=>`<div class="category-row"><span><b>${esc(c.name)}</b><small>${esc(c.group)} · ${c.custom?'Özel kategori':'Başlangıç kataloğu'}</small></span><button class="btn small ${c.custom?'quiet':''}" data-action="toggle-category-${c.id}">${c.custom?'Kaldır':'Gizle'}</button></div>`).join('')}</div>`:'<p>Bu başlıkta aramayla eşleşen kategori yok.</p>'}</section>`}).join('')}</div><div class="notice">196 başlangıç seçeneği, ilan ve talep arama niyetlerini kapsayan ürün taksonomisidir; platformun gerçek arama ölçümü değildir. Kullanım verisi biriktikçe sıralama analitikle güncellenebilir.</div>`}
function page(){switch(state.page){case'home':return home();case'dashboard':return shell(dashboard());case'matches':return shell(matchesView());case'leads':return shell(leadsView());case'properties':return shell(propertiesView());case'offers':return shell(offersView());case'chat':return shell(chatView());case'appointments':return shell(appointmentsView());case'tokens':return shell(tokensView());case'admin':return shell(adminView()+leadModerationView());case'superadmin':return shell(superadminView()+adminView()+leadModerationView());case'categories':return shell(categoriesView());default:return shell(dashboard())}}
function render(){document.body.classList.toggle('dark-market',state.page==='leads'&&(state.role==='b2b'||state.role==='developer'));app.innerHTML=page();if(modal)drawModal()}
function drawModal(){let target=document.querySelector('.modal-backdrop');if(!target){document.body.insertAdjacentHTML('beforeend','<div class="modal-backdrop" id="modal-root"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"></section></div>');target=document.querySelector('#modal-root');target.addEventListener('click',e=>{if(e.target===target)closeModal()})}let box=target.querySelector('.modal');box.innerHTML=`<div class="modal-head"><h3 id="modal-title">${modal.title}</h3><button class="icon-btn" data-action="close-modal" aria-label="Kapat">×</button></div><div class="separator"></div>${modal.body}`}
function closeModal(){modal=null;document.querySelector('#modal-root')?.remove()}
function openModal(title,body){modal={title,body};render()}
function field(label,id,placeholder='',value='',type='text',hint=''){return `<div class="field"><label for="${id}">${label}</label><input id="${id}" type="${type}" placeholder="${placeholder}" value="${esc(value)}">${hint?`<small>${hint}</small>`:''}</div>`}
function startBudget(){budgetStep=0;budgetVals={income:'',debt:'',down:'',term:'60',energyClass:'other',ownsHome:false};budgetRender()}
function budgetRender(){
 const labels=['Aylık net geliriniz?','Mevcut aylık kredi / borç ödemeniz?','Peşinatınız?','Kaç ay vade düşünüyorsunuz?'];let body='';
 if(budgetStep<3){let key=['income','debt','down'][budgetStep];body=`<div class="wizard-step">BÜTÇE SİMÜLASYONU · ${budgetStep+1} / 4</div><h2>${labels[budgetStep]}</h2><p class="wizard-desc">Aylık TL tutarını gir. Sonuç yaklaşık bir demo hesaplamasıdır.</p>${field(labels[budgetStep],key,'Örn. 75.000',budgetVals[key],'number')}`}
 else if(budgetStep===3){const snap=CasaServices.economicSnapshot;body=`<div class="wizard-step">BÜTÇE SİMÜLASYONU · 4 / 4</div><h2>${labels[3]}</h2><p class="wizard-desc">Güncel piyasa oranı, vade ve BDDK kredi/değer sınırlarıyla yaklaşık hesabını yap.</p><div class="choice-grid">${[12,24,36,48,60,120].map(n=>`<button class="choice ${budgetVals.term==n?'selected':''}" data-term="${n}">${n} ay</button>`).join('')}</div><div class="budget-reg-card"><b>TCMB ortalama konut kredisi oranı · %${snap.housingLoanAnnualRate} yıllık</b><span>Veri dönemi: ${snap.rateDate} · Aylık yaklaşık %${(snap.housingLoanAnnualRate/12).toFixed(3)}</span><span>Politika faizi: %${snap.policyRate} · Kredi faiziyle aynı değildir.</span><a href="${snap.rateSource}" target="_blank" rel="noopener">TCMB haftalık kredi faizi verisi ↗</a></div><label class="field"><span>Enerji sınıfı</span><select id="budget-energy"><option value="ab" ${budgetVals.energyClass==='ab'?'selected':''}>A / B</option><option value="c" ${budgetVals.energyClass==='c'?'selected':''}>C</option><option value="other" ${budgetVals.energyClass==='other'?'selected':''}>Diğer / bilinmiyor</option></select></label><label class="checkrow"><input id="budget-owner" type="checkbox" ${budgetVals.ownsHome?'checked':''}> Benim, eşimin veya 18 yaş altı çocuğumun adına konut var</label><p class="budget-source-note">BDDK konut değerine göre azami kredi oranı: <a href="${snap.ltvSource}" target="_blank" rel="noopener">11364 sayılı karar (${snap.ltvDate}) ↗</a>. Gelirin %35’i borç ödemesine ayrılabilir varsayımı simülasyon varsayımıdır; BDDK kuralı değildir. Mevcut konut sahipliği halinde kredi/değer oranına mevzuattaki indirim uygulanır.</p>`}
 else{const estimate=CasaServices.budget.estimate({income:+budgetVals.income||75000,debt:+budgetVals.debt||0,downPayment:+budgetVals.down||1000000,termMonths:+budgetVals.term,energyClass:budgetVals.energyClass,ownsHome:budgetVals.ownsHome});state.budget=estimate;save();body=`<div class="wizard-step">ÖN HESAPLAMA TAMAMLANDI</div><h2>Yaklaşık bütçen hazır.</h2><div class="result-card"><p>Ön tahmini satın alma bütçen</p><div class="result-number">${money(estimate.low)} — ${money(estimate.high)}</div><p>${estimate.disclaimer}</p></div><div class="budget-result-grid"><div><span>Tahmini azami konut kredisi</span><b>${money(estimate.maxLoan)}</b></div><div><span>Varsayılan aylık taksit kapasitesi</span><b>${money(estimate.monthlyPayment)}</b></div><div><span>Simülasyonda kullanılan oran</span><b>%${estimate.annualRate} yıllık · %${estimate.monthlyRate.toFixed(3)} aylık</b></div><div><span>Vade · enerji sınıfı · azami kredi/değer</span><b>${estimate.termMonths} ay · ${estimate.energyClass.toUpperCase()} · %${(estimate.ltv*100).toFixed(0)}</b></div></div><div class="budget-source-note">Veri dönemi: ${estimate.snapshotDate}. <a href="${CasaServices.economicSnapshot.rateSource}" target="_blank" rel="noopener">TCMB konut kredisi verisi</a> · <a href="${CasaServices.economicSnapshot.policySource}" target="_blank" rel="noopener">TCMB politika faizi açıklaması</a> · <a href="${CasaServices.economicSnapshot.ltvSource}" target="_blank" rel="noopener">BDDK 11364 sayılı karar</a>. Kredi tutarı gelir taksit kapasitesiyle BDDK kredi/değer sınırının düşük olanına göre tahmin edilir.</div><div style="margin-top:20px">${b('Bu bütçeyle ne aradığımı belirle','start-lead','btn primary full')}</div>`}
 const actions=budgetStep<=3?`<div class="wizard-actions">${budgetStep?b('Geri','budget-back','btn'):b('İptal','close-modal','btn quiet')} ${b(budgetStep===3?'Bütçemi hesapla':'Devam et','budget-next','btn primary')}</div>`:`<div style="margin-top:15px;text-align:right">${b('Düzenle','budget-edit','btn small')}</div>`;openModal('Bütçeni hesapla',body+actions);
}
function startLead(edit=false){wizard={step:edit?0:0,edit};leadRender()}
function leadRender(){let steps=[['Nerede arıyorsun?','place',['Fethiye','Dalaman','Ortaca','Seydikemer','Marmaris','Bodrum']],['Gayrimenkul / taşınmaz kategorisi','category',[]],['Kaç oda?','rooms',['1+0','1+1','2+1','3+1','4+1','5+']],['Ne amaçla?','purpose',['Oturmak','Yatırım','Tatil','Kiralama']],['Ne zaman?','when',['Hemen','1–3 ay','3–6 ay','6+ ay']]];let s=steps[wizard.step];let current=wizard.edit&&state.lead?state.lead:{};let defaults=['Fethiye','Daire','2+1','Oturmak','1–3 ay'];let selected=wizard.answers?.[s[1]]||current[s[1]]||defaults[wizard.step];const categoryControl=wizard.step===1?`<label class="field"><span>Kategori seç · ${allCategories().length} seçenek</span><select id="lead-category"><option value="">Kategori seç</option>${categoryOptions(wizard.answers?.categoryId||current.categoryId)}</select></label>`:'';let body=`<div class="wizard-step">${wizard.edit?'TALEBİNİ DÜZENLE':`TALEP OLUŞTUR · ${wizard.step+1} / 5`}</div><h2>${wizard.edit?'Talebini güncelle':s[0]}</h2><p class="wizard-desc">${wizard.step===0?'Aradığın bölgeyi seç. Birden fazla bölge ekleyebilirsin.':wizard.step===1?'İki ana başlık altında kategori arayabilir ve ihtiyacına uygun ilan türünü seçebilirsin.':'Sana en uygun seçenekleri bulmamıza yardımcı ol.'}</p>${categoryControl}${wizard.step===1?`<div class="notice">Gayrimenkul ve Taşınmaz ana başlıklarında ${CasaCategories.total} başlangıç kategorisi bulunur.</div>`:`<div class="choice-grid">${s[2].map(v=>`<button class="choice ${selected===v?'selected':''}" data-select="${s[1]}" data-value="${v}">${v}</button>`).join('')}</div>`}${wizard.step===0?field('Bölge ara','place-search','Örn. Fethiye, Muğla') :''}<div class="wizard-actions">${wizard.step?b('Geri','lead-back','btn'):b('İptal','close-modal','btn quiet')} ${b(wizard.edit?'Kaydet':wizard.step===4?'Talebimi oluştur':'Devam et','lead-next','btn primary')}</div>`;openModal('Talep oluştur',body)}
function verification(){openModal('Talebini doğrula',`<p>Talebini eşleşmelere açmadan önce iletişim bilgilerini doğrula.</p><div class="verify-steps"><div class="verify-line"><span>Telefon numarası · +90 532 555 01 24</span><span class="tag">DOĞRULANDI</span></div><div class="verify-line"><span>E-posta · ahmet@example.demo</span><span class="tag">DOĞRULANDI</span></div></div><div class="notice" style="margin-top:14px">Demo doğrulama kodu: <b>123456</b>. Gerçek SMS veya e-posta gönderilmez.</div>${field('Demo doğrulama kodu','otp','123456','','text')}<div style="margin-top:18px">${b('Talebimi doğrula','verify','btn primary full')}</div>`)}
function runMatching(){openModal('Talebin doğrulandı',`<div class="result-card"><div class="eyebrow" style="color:#d5e2d7">EŞLEŞME ANALİZİ</div><h2 style="margin-top:16px;color:white">Senin için uygun portföyleri buluyoruz...</h2><div class="progress"><span style="width:30%" id="match-progress"></span></div><div class="timeline">${['Bütçe','Konum','Gayrimenkul tipi','Oda sayısı','İhtiyaç','Portföy doğrulama'].map(x=>`<div class="timeline-row done"><span class="dot">✓</span><span style="color:white">${x}</span></div>`).join('')}</div></div><p>Demo eşleşme analizi sürüyor.</p>`);CasaServices.matching.find().then(result=>{state.matches=true;state.matchCount=result.count;save();openModal(`${result.count} uygun eşleşme bulundu`,`<div class="result-card"><div class="result-number">${result.count} uygun eşleşme</div><p>Fethiye ve çevresinde talebine uygun doğrulanmış portföyler hazır.</p></div>${b('Eşleşmeleri gör','see-matches','btn primary full')}`)})}
function propertyDetail(i){let p=properties[i]||properties[0];openModal(p.title,`<div class="listing-image" style="background-image:url('${p.photo}')"></div><div class="property-row"><span class="tag">Doğrulanmış profesyonel portföyü</span><span class="tag">%${p.score} eşleşme</span></div><h2 style="margin-top:15px">${p.price}</h2><p>${p.place} · ${p.sqm} · ${p.rooms}</p><div class="separator"></div><h3>Öne çıkanlar</h3><p>${p.features}</p><div class="callout"><b>Neden eşleşti?</b><br>${p.why}</div><p style="margin-top:13px;font-size:12px">Fethiye Prime Gayrimenkul · Profesyonel portföy</p><div class="grid cols-2" style="margin-top:15px">${b('İlgileniyorum','interest','btn primary')}${b('Mesaj gönder','interest','btn')}</div><p style="font-size:11px;margin:12px 0 0">Telefon numarası karşılıklı iletişim onayına kadar gizlidir.</p>`)}
function accessLead(i){let l=leads[i];if(state.role==='b2c'){state.page='chat';state.chatStarted=true;save();render();return}if(state.activeLead&&i===0){openModal('Talep detayları',`<div class="tag gold">${l.tier} · ${l.token} COIN</div><h2 style="margin-top:15px">Ahmet Yılmaz · ${l.place}</h2><p>${l.rooms} · ${money(l.budgetTotal)} toplam bütçe · ${l.purpose} · ${l.timing}</p><div class="callout">Telefon ve e-posta karşılıklı onay verilene kadar gizlidir.</div><div class="grid cols-2" style="margin-top:18px">${b('Uygun portföy gönder','choose-property','btn primary')}${b('Benzer portföyüm var','add-property','btn')}</div>`);return}openModal('Talebe eriş',`<div class="result-card"><p>Bu talebe erişmek</p><div class="result-number">${l.token} Coin kullanacak.</div><p>Mevcut bakiyen: ${state.token} Coin</p></div><p>${l.place} · ${l.rooms} · ${l.budget}</p><div class="wizard-actions">${b('Vazgeç','close-modal','btn')}${b('Eriş','confirm-access-'+i,'btn primary')}</div>`)}
function addPropertyModal(){openModal(state.role==='developer'?'Proje ekle':'Portföy ekle',`<p>İlan bağlantısını yapıştır; demo otomatik bilgi çıkarımı yapsın.</p>${field('İlan bağlantısı','listing-url','https://www.sahibinden.com/ilan/...') }<label class="field"><span>İlan kategorisi</span><select id="listing-category"><option value="">Kategori seç</option>${categoryOptions()}</select></label><div class="notice">196 başlangıç kategorisi Gayrimenkul ve Taşınmaz ana başlıklarına ayrılmıştır. Gerçek scraping yapılmaz.</div><div style="margin-top:18px">${b('Portföyü kontrol et','extract','btn primary full')}</div>`)}
function extraction(){openModal('Bilgiler otomatik olarak çıkarıldı',`<div class="verify-steps">${['Başlık bulundu','Fiyat bulundu','Konum bulundu','m² bulundu','Oda bilgisi bulundu','Fotoğraflar bulundu'].map(x=>`<div class="verify-line"><span>${x}</span><span class="tag">✓</span></div>`).join('')}</div><div class="separator"></div><div class="grid cols-2">${field('Başlık','ex-title','2+1 Daire','Fethiye Merkez 2+1','text')}${field('Fiyat','ex-price','₺','5250000','number')}${field('Konum','ex-place','Fethiye','Fethiye Merkez')}${field('m²','ex-sqm','110','110','number')}</div>${field('İlan bağlantısı','ex-url','',document.querySelector('#listing-url')?.value||'https://ornek.demo/ilan/2419')}<div class="notice">Otomatik kontrol · Fiyat ✓ · Konum ✓ · İlan aktifliği ✓ · Veri tutarlılığı ✓ · Duplicate kontrolü ✓</div><p style="margin-top:14px"><span class="tag gold">MANUEL DOĞRULAMA BEKLİYOR</span></p><div style="margin-top:16px">${b('Portföyü kaydet','save-property','btn primary full')}</div>`)}
function reviewProperty(){openModal('Manuel portföy doğrulama',`<div class="card soft"><h3>Fethiye Merkez · 2+1 Daire</h3><p>₺5.250.000 · 110 m² · Fethiye Prime Gayrimenkul</p><div class="callout">Otomatik kontroller tamamlandı. Manuel inceleme kararı bekleniyor.</div></div><div class="grid cols-3" style="margin-top:18px">${b('Onayla','approve-property','btn primary')}${b('Revizyon iste','revise-property','btn')}${b('Reddet','reject-property','btn quiet')}</div>`)}
function appointmentModal(){openModal('Randevu oluştur',`${field('Tarih','appt-date','','2026-10-10','date')}${field('Saat','appt-time','','14:00','time')}${field('Not','appt-note','Kısa not (isteğe bağlı)')}<div style="margin-top:16px">${b('Randevu oluştur','save-appointment','btn primary full')}</div>`)}
function rolesModal(){openModal('Demo rolünü seç',`<p>Rollerin yönetim kapsamı prototipte ayrıştırılmıştır.</p><div class="grid">${[['b2c','B2C Demo','Alıcı · kategori seçimi ve talep oluşturma'],['b2b','Emlak Demo','Emlak ofisi · ilan/lead ve Coin işlemleri'],['developer','İnşaat Demo','Proje geliştirici · proje portföyü ve talepler'],['admin','Admin Demo','Operasyon · ilan doğrulama ve içerik moderasyonu'],['superadmin','Süperadmin Demo','Tam yetki · admin hesapları, kategori ve platform yönetimi']].map(x=>`<button class="choice" data-role="${x[0]}"><b>${x[1]}</b><br><span class="label">${x[2]}</span></button>`).join('')}</div><p class="notice">Demo rol seçimi gerçek kimlik doğrulama değildir.</p>`)}
function createAdminForm(){if(state.role!=='superadmin'){toast('Admin hesaplarını yalnızca süperadmin yönetebilir.');return}openModal('Admin hesabı ekle',`${field('Ad soyad','admin-name','Örn. Bölge Operasyon Admini')}${field('E-posta','admin-email','admin@casaporta.demo','')}<div class="notice">Bu demo hesabı yalnızca tarayıcıda kaydedilir; gerçek kullanıcı daveti gönderilmez.</div><div style="margin-top:15px">${b('Admin hesabını ekle','create-admin','btn primary full')}</div>`)}
function offersModal(){openModal('Uygun portföy gönder',`<p>Ahmet’in talebine uygun mevcut portföyünden seçim yap.</p>${properties.slice(0,3).map((p,i)=>`<label class="verify-line"><span><input type="radio" name="offer-property" value="${i}" ${i===0?'checked':''}> ${p.title} · ${p.price}</span><span class="tag">%${p.score}</span></label>`).join('')}<div style="margin-top:16px">${b('Teklif gönder','send-offer','btn primary full')}</div>`)}
function feedbackModal(){openModal('Görüşmenin sonucu ne oldu?',`<p>Bu geri bildirim eşleşmelerin kalitesini artırmaya yardımcı olur.</p><div class="choice-grid">${['Görüşüldü','Teklif verildi','Satın alındı','Kiralandı','Vazgeçildi','Devam ediyor'].map(x=>`<button class="choice" data-feedback="${x}">${x}</button>`).join('')}</div>${field('Paylaşmak istediğin bir şey var mı?','feedback-note','Kısa geri bildirim (isteğe bağlı)')}<div style="margin-top:16px">${b('Geri bildirimi gönder','save-feedback','btn primary full')}</div>`)}
function packagesModal(){let pkgs=state.role==='developer'?['Starter','Pro','Enterprise']:['Starter','Pro','Elite'];openModal('İşine uygun paket',`<p>Paket özellikleri demo yapılandırmasından gelir.</p><div class="grid cols-3">${pkgs.map((x,i)=>`<div class="card"><span class="tag">${x}</span><h3 style="margin-top:14px">${['₺0','₺2.490','₺6.990'][i]}<span class="label"> / ay</span></h3><div class="timeline" style="margin-top:18px">${[['Dahil Coin',`${[30,100,350][i]}`],['Aktif portföy',`${[5,20,80][i]}`],['Aktif proje',`${[0,2,10][i]}`],['Kullanıcı',`${[1,3,10][i]}`],['Öncelikli eşleşme',i?'Dahil':'—'],['Analitik',i===2?'Gelişmiş':'Temel'],['API erişimi',i===2?'Dahil':'—']].map(r=>`<div style="font-size:12px;padding:5px 0;border-bottom:1px solid var(--line)"><span class="muted">${r[0]}</span><b style="float:right">${r[1]}</b></div>`).join('')}</div>${b('Paketi seç','select-package-'+x,'btn '+(i===1?'primary':'')+' full')}</div>`).join('')}</div><p style="font-size:11px;margin-top:14px">Paketler bu demoda örnek konfigürasyon değerleri kullanır. Gerçek ödeme alınmaz.</p>`)}
function coinPacksModal(){openModal('Coin paketi seç',`<p>Coin bakiyen azaldığında paket alıp taleplere erişmeye devam et.</p><div class="grid cols-2">${CasaServices.coinPacks.map(pack=>`<article class="card coin-pack ${pack.featured?'featured':''}">${pack.featured?'<span class="tag gold">EN ÇOK TERCİH EDİLEN</span>':''}<h3 style="margin-top:12px">${pack.name}</h3><div class="coin-pack-amount">◉ ${pack.coins} Coin</div>${pack.badge?`<p class="coin-bonus">${pack.badge}</p>`:'<p class="coin-bonus">Hemen kullanılabilir</p>'}<div class="coin-pack-price">${money(pack.price)}</div>${b('Demo alımını tamamla','buy-coin-pack-'+pack.id,'btn primary full')}</article>`).join('')}</div><p class="notice" style="margin-top:15px">Demo satın alımıdır. Gerçek ödeme alınmaz; kart veya ödeme bilgisi istenmez. Seçtiğin Coin anında bakiyene eklenir.</p>`)}
document.addEventListener('click',e=>{
 const nav=e.target.closest('[data-nav]');if(nav){state.page=nav.dataset.nav;if(state.page==='dashboard'&&state.role==='b2c'&&!state.lead)state.page='dashboard';save();closeModal();render();return}
 const sel=e.target.closest('[data-select]');if(sel){wizard.answers=wizard.answers||{};wizard.answers[sel.dataset.select]=sel.dataset.value;leadRender();return}
 const term=e.target.closest('[data-term]');if(term){budgetVals.term=term.dataset.term;budgetRender();return}
 const role=e.target.closest('[data-role]');if(role){state.role=role.dataset.role;state.page=state.role==='admin'?'admin':state.role==='superadmin'?'superadmin':'dashboard';save();closeModal();render();return}
 const fb=e.target.closest('[data-feedback]');if(fb){wizard.feedback=fb.dataset.feedback;document.querySelectorAll('[data-feedback]').forEach(x=>x.classList.toggle('selected',x===fb));return}
 const action=e.target.closest('[data-action]')?.dataset.action;if(!action)return;
 if(action==='budget'){closeModal();startBudget()}
 else if(action==='how'){document.querySelector('#how')?.scrollIntoView({behavior:'smooth'});if(!document.querySelector('#how')){state.page='home';render();setTimeout(()=>document.querySelector('#how')?.scrollIntoView({behavior:'smooth'}),30)}}
 else if(action==='roles')rolesModal();else if(action==='role-b2b'){state.role='b2b';state.page='dashboard';save();render()}
 else if(action==='create-admin-form')createAdminForm()
 else if(action==='create-admin'){if(state.role!=='superadmin'){toast('Bu işlem yalnızca süperadmin yetkisindedir.');return}const name=document.querySelector('#admin-name')?.value.trim(),email=document.querySelector('#admin-email')?.value.trim();if(!name||!email||!email.includes('@')){toast('Geçerli ad ve e-posta gir.');return}state.adminUsers.push({id:'admin-'+Date.now(),name,email,role:'admin',active:true});save();closeModal();render();toast('Demo admin hesabı eklendi.')}
 else if(action.startsWith('toggle-admin-')){if(state.role!=='superadmin'){toast('Admin hesaplarını yalnızca süperadmin yönetebilir.');return}const admin=state.adminUsers.find(a=>a.id===action.replace('toggle-admin-',''));if(admin){admin.active=!admin.active;save();render();toast(admin.active?'Admin erişimi açıldı.':'Admin erişimi kapatıldı.')}}
 else if(action.startsWith('moderate-lead-')){if(!isAdmin()){toast('Talep moderasyonu admin ve süperadmin yetkisindedir.');return}const index=+action.replace('moderate-lead-','');if((state.moderatedLeadIds||[]).includes(index))state.moderatedLeadIds=state.moderatedLeadIds.filter(i=>i!==index);else state.moderatedLeadIds.push(index);save();render();toast(state.moderatedLeadIds.includes(index)?'Talep yayından gizlendi.':'Talep yeniden yayına alındı.')}
 else if(action==='create-category'){if(state.role!=='superadmin'){toast('Kategorileri yalnızca süperadmin yönetebilir.');return}const name=document.querySelector('#new-category-name')?.value.trim(),rootId=document.querySelector('#new-category-root')?.value,root=CasaCategories.roots.find(item=>item.id===rootId);if(!name||!root){toast('Kategori adı gir ve ana başlık seç.');return}if(allCategories().some(c=>c.name.toLocaleLowerCase('tr-TR')===name.toLocaleLowerCase('tr-TR'))){toast('Bu kategori zaten mevcut.');return}state.categories.push({id:'custom-'+Date.now(),rootId,rootTitle:root.title,group:'Özel kategori',assetType:name,intent:'Özel',name,active:true,custom:true});save();render();toast('Kategori kataloğa eklendi.')}
 else if(action.startsWith('toggle-category-')){if(state.role!=='superadmin'){toast('Kategorileri yalnızca süperadmin yönetebilir.');return}const id=action.replace('toggle-category-',''),custom=state.categories.findIndex(c=>c.id===id);if(custom>=0){state.categories.splice(custom,1)}else if(state.disabledCategoryIds.includes(id)){state.disabledCategoryIds=state.disabledCategoryIds.filter(item=>item!==id)}else{state.disabledCategoryIds.push(id)}save();render();toast('Kategori görünürlüğü güncellendi.')}
 else if(action==='filter-categories'){if(state.role!=='superadmin'){toast('Bu panel yalnızca süperadmin rolüne açıktır.');return}state.categorySearch=document.querySelector('#category-search')?.value||'';save();render()}
 else if(action==='clear-category-search'){state.categorySearch='';save();render()}
 else if(action==='reset'){state=seed();save();closeModal();render();toast('Demo verileri sıfırlandı.')}
 else if(action==='close-modal')closeModal();else if(action==='budget-back'){budgetStep=Math.max(0,budgetStep-1);budgetRender()}
 else if(action==='budget-edit'){budgetStep=0;budgetRender()}
 else if(action==='budget-next'){if(budgetStep<3){if(budgetStep===0)budgetVals.income=document.querySelector('#income')?.value||'75000';if(budgetStep===1)budgetVals.debt=document.querySelector('#debt')?.value||'0';if(budgetStep===2)budgetVals.down=document.querySelector('#down')?.value||'1000000';budgetStep++;budgetRender()}else if(budgetStep===3){budgetVals.energyClass=document.querySelector('#budget-energy')?.value||'other';budgetVals.ownsHome=!!document.querySelector('#budget-owner')?.checked;budgetStep++;budgetRender()}}
 else if(action==='start-lead'){closeModal();wizard={step:0,edit:false,answers:{}};leadRender()}
 else if(action==='lead-back'){wizard.step=Math.max(0,wizard.step-1);leadRender()}
 else if(action==='lead-next'){wizard.answers=wizard.answers||{};if(wizard.edit){state.lead=CasaServices.lead.update(state.lead,wizard.answers);save();closeModal();render();toast('Talebin güncellendi.');return}if(wizard.step===1){const category=allCategories().find(c=>c.id===document.querySelector('#lead-category')?.value);if(!category){toast('Devam etmek için bir kategori seç.');return}wizard.answers.categoryId=category.id;wizard.answers.categoryName=category.name;wizard.answers.categoryRoot=category.rootTitle;wizard.answers.type=category.assetType}let key=['place','type','rooms','purpose','when'][wizard.step];if(!wizard.answers[key])wizard.answers[key]=['Fethiye','Daire','2+1','Oturmak','1–3 ay'][wizard.step];if(wizard.step<4){wizard.step++;leadRender()}else{state.lead=CasaServices.lead.create(wizard.answers);state.page='dashboard';save();closeModal();verification()}}
 else if(action==='verify'){let otp=document.querySelector('#otp')?.value;if(!CasaServices.verification.verify(otp)){toast('Demo kodu 123456 olmalı.');return}state.verified=true;save();runMatching()}
 else if(action==='see-matches'||action==='nav-matches'){state.matches=true;state.page='matches';save();closeModal();render()}
 else if(action==='nav-chat'){state.page='chat';if(state.role!=='b2c')state.chatStarted=true;save();closeModal();render()}
 else if(action==='nav-leads'){state.page='leads';save();closeModal();render()}
 else if(action==='nav-properties'){state.page='properties';save();closeModal();render()}
 else if(action==='nav-tokens'){state.page='tokens';save();closeModal();render()}
 else if(action==='nav-categories'){if(state.role!=='superadmin'){toast('Kategori yönetimi sadece süperadmin yetkisindedir.');return}state.page='categories';save();closeModal();render()}
 else if(action==='nav-admin'){if(!isAdmin()){toast('Bu panele erişim yetkin yok.');return}state.page='admin';save();closeModal();render()}
 else if(action==='nav-superadmin'){if(state.role!=='superadmin'){toast('Bu panele erişim yetkin yok.');return}state.page='superadmin';save();closeModal();render()}
 else if(action.startsWith('property-'))propertyDetail(+action.split('-')[1]);else if(action.startsWith('interested-')){state.interested=true;state.chatStarted=true;state.page='chat';save();render();toast('İlgin firmaya iletildi. Mesajlaşma açıldı.')}
 else if(action==='interest'){state.interested=true;state.chatStarted=true;state.page='chat';save();closeModal();render();toast('İlgin firmaya iletildi.')}
 else if(action.startsWith('access-'))accessLead(+action.split('-')[1]);else if(action.startsWith('confirm-access-')){let i=+action.split('-')[2],l=leads[i];if(!CasaServices.coins.access(state,l)){toast('Coin bakiyesi yetersiz.');return}state.chatStarted=true;save();closeModal();openModal('Talep detayları',`<div class="tag gold">${l.tier} · ${l.token} COIN</div><h2 style="margin-top:15px">Ahmet Yılmaz · ${l.place}</h2><p>${l.rooms} · ${l.budget} · ${l.purpose} · 1–3 ay içinde</p><div class="callout">Telefon ve e-posta karşılıklı onay verilene kadar gizlidir.</div><div class="grid cols-2" style="margin-top:18px">${b('Uygun portföy gönder','choose-property','btn primary')}${b('Benzer portföyüm var','add-property','btn')}</div>`);toast(`${l.token} Coin kullanıldı.`)}
 else if(action==='choose-property')offersModal();else if(action==='send-offer'){let chosen=document.querySelector('[name="offer-property"]:checked'),p=properties[+(chosen?.value||0)];state.offers.unshift(CasaServices.offer.create(p));state.chatStarted=true;CasaServices.chat.send(state,'b2b',`Talebinize uygun ${p.title.toLowerCase()} portföyümüzü sizinle paylaştım.`);save();closeModal();state.page='offers';render();toast('Teklif gönderildi.')}
 else if(action==='add-property'){addPropertyModal()}
 else if(action==='extract'){const url=document.querySelector('#listing-url')?.value||document.querySelector('#ex-url')?.value;if(!url){toast('Devam etmek için bir ilan bağlantısı gir.');return}const selectedCategory=allCategories().find(c=>c.id===document.querySelector('#listing-category')?.value);if(document.querySelector('#listing-category')&&!selectedCategory){toast('Portföy için kategori seç.');return}state.selectedListingCategory=selectedCategory?.name||state.selectedListingCategory;state.extraction=CasaServices.property.extract(url);extraction()}
 else if(action==='save-property'){CasaServices.property.save(state);save();closeModal();state.page=state.role==='admin'?'admin':'properties';render();toast('Portföy kaydedildi. Manuel doğrulama bekliyor.')}
 else if(action==='review-property'||action==='review-sample'){if(!isAdmin()){toast('İlan inceleme yetkisi admin ve süperadmindedir.');return}reviewProperty()}
 else if(action==='approve-property'){if(!isAdmin()){toast('İlan onaylama yetkisi admin ve süperadmindedir.');return}CasaServices.property.approve(state);save();closeModal();render();toast('Portföy onaylandı ve aktif oldu.')}
 else if(action==='revise-property'||action==='reject-property'){closeModal();toast(action==='revise-property'?'Revizyon talebi oluşturuldu.':'Portföy reddedildi.');if(action==='reject-property'){state.propertyAdded=false;save();render()}}
 else if(action==='edit-lead'){wizard={step:0,edit:true,answers:{}};leadRender()}
 else if(action==='pause'){state.paused=!state.paused;save();render();toast(state.paused?'Talebin duraklatıldı.':'Talebin yeniden aktif.')}
 else if(action==='renew'){state.paused=false;save();render();toast('Talebin yenilendi.')}
 else if(action==='close-lead'){state.lead=null;state.matches=false;state.verified=false;save();render();toast('Talebin kapatıldı.')}
 else if(action==='send-message'){let input=document.querySelector('#message-input'),msg=input?.value.trim();if(!msg){toast('Önce mesajını yaz.');return}CasaServices.chat.send(state,state.role,msg);save();render()}
 else if(action==='unlock-contact'){let opened=CasaServices.contactUnlock.approve(state,state.role);save();render();toast(opened?'İletişim bilgileri açıldı.':`Onayın kaydedildi. Diğer tarafın onayı bekleniyor.`)}
 else if(action==='appointment')appointmentModal()
 else if(action==='save-appointment'){let date=document.querySelector('#appt-date')?.value,time=document.querySelector('#appt-time')?.value;if(!date||!time){toast('Tarih ve saat seç.');return}state.appointments.push(CasaServices.appointment.create({date,time,note:document.querySelector('#appt-note')?.value||'Fethiye Prime Gayrimenkul ile görüşme'}));save();closeModal();state.page='appointments';render();toast('Randevu oluşturuldu.')}
 else if(action==='feedback')feedbackModal();else if(action==='save-feedback'){state.feedback={choice:wizard.feedback||'Devam ediyor',note:document.querySelector('#feedback-note')?.value||''};save();closeModal();toast('Geri bildirimin kaydedildi.')}
 else if(action==='buy-coins')coinPacksModal();else if(action.startsWith('buy-coin-pack-')){let id=action.replace('buy-coin-pack-',''),pack=CasaServices.coinPacks.find(item=>item.id===id),result=CasaServices.coins.purchase(state,pack);if(!result.ok){toast('Coin paketi şu anda alınamıyor.');return}save();closeModal();render();toast(`${pack.coins} Coin eklendi. Yeni bakiye: ${result.balance} Coin.`)}
 else if(action==='packages')packagesModal();else if(action.startsWith('select-package-')){closeModal();toast(`${action.replace('select-package-','')} paketi demo olarak seçildi.`)}
 else if(action==='project-detail')openModal('Fethiye Modern',`<div class="listing-image" style="background-image:url('${photos[3]}')"></div><span class="tag">AKTİF PROJE</span><h2 style="margin-top:15px">32 daire · Teslim 2027</h2><p>1+1 / 2+1 / 3+1 · Fethiye</p>${b('Proje taleplerini gör','nav-leads','btn primary full')}`)
 else if(action==='nav-dashboard'){state.page='dashboard';save();render()}
});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if(e.key==='Enter'&&e.target.id==='message-input'){e.preventDefault();document.querySelector('[data-action="send-message"]')?.click()}});
render();
